/**
 * Shared Israeli calendar (post-launch week 1 spec, task A2). Used by the Ads Bot graduation
 * timing gate (G8) and the WhatsApp nurture scheduler (B1).
 *
 * Blackout dates come only from `il-blackout-dates.generated.ts`, generated by
 * `scripts/build-il-calendar.mjs` from Hebcal's Israel holiday feed; that file's header names
 * the source URL and fetch date. Never type dates here by hand.
 *
 * All local-time math uses `Intl` with the Asia/Jerusalem zone, so DST changes (late March /
 * late October) are handled by the platform's tz database, not by a fixed offset.
 * Pure: no I/O.
 */
import { IL_BLACKOUT_DATES, IL_CALENDAR_COVERAGE, IL_CALENDAR_SOURCE } from './il-blackout-dates.generated';

export { IL_BLACKOUT_DATES, IL_CALENDAR_COVERAGE, IL_CALENDAR_SOURCE };

export const ISRAEL_TIME_ZONE = 'Asia/Jerusalem';

/** 0 = Sunday … 6 = Saturday (same convention as `Date#getUTCDay`). */
export type Weekday = 0 | 1 | 2 | 3 | 4 | 5 | 6;

export interface IsraelLocalParts {
  /** Israel calendar date, `YYYY-MM-DD`. */
  isoDate: string;
  year: number;
  month: number;
  day: number;
  weekday: Weekday;
  hour: number;
  minute: number;
}

const FORMATTER = new Intl.DateTimeFormat('en-US', {
  timeZone: ISRAEL_TIME_ZONE,
  hourCycle: 'h23',
  year: 'numeric',
  month: '2-digit',
  day: '2-digit',
  hour: '2-digit',
  minute: '2-digit',
  second: '2-digit',
  weekday: 'short',
});

const WEEKDAYS: Record<string, Weekday> = { Sun: 0, Mon: 1, Tue: 2, Wed: 3, Thu: 4, Fri: 5, Sat: 6 };
const ISO_DATE = /^\d{4}-\d{2}-\d{2}$/;
const DAY_MS = 86_400_000;

/** Weekday, hour and minute (plus the calendar date) of an instant in Asia/Jerusalem. */
export function israelLocalParts(date: Date): IsraelLocalParts {
  if (!(date instanceof Date) || Number.isNaN(date.getTime())) throw new Error('israelLocalParts: invalid date');
  const parts: Record<string, string> = {};
  for (const p of FORMATTER.formatToParts(date)) parts[p.type] = p.value;
  const year = Number(parts.year);
  const month = Number(parts.month);
  const day = Number(parts.day);
  const weekday = WEEKDAYS[parts.weekday];
  if (weekday === undefined) throw new Error(`israelLocalParts: unexpected weekday ${parts.weekday}`);
  return {
    isoDate: `${parts.year}-${parts.month}-${parts.day}`,
    year,
    month,
    day,
    weekday,
    hour: Number(parts.hour),
    minute: Number(parts.minute),
  };
}

/** Israel calendar date (`YYYY-MM-DD`) of an instant. */
export function israelDate(date: Date): string {
  return israelLocalParts(date).isoDate;
}

/** Pure calendar arithmetic on `YYYY-MM-DD` (no time zone involved). */
export function addDaysIso(isoDate: string, days: number): string {
  if (!ISO_DATE.test(isoDate)) throw new Error(`addDaysIso: bad date ${isoDate}`);
  return new Date(Date.parse(`${isoDate}T00:00:00Z`) + days * DAY_MS).toISOString().slice(0, 10);
}

/** Whole calendar days from `from` to `to` (`to - from`), both `YYYY-MM-DD`. */
export function daysBetweenIso(from: string, to: string): number {
  if (!ISO_DATE.test(from) || !ISO_DATE.test(to)) throw new Error('daysBetweenIso: bad date');
  return Math.round((Date.parse(`${to}T00:00:00Z`) - Date.parse(`${from}T00:00:00Z`)) / DAY_MS);
}

/** Weekday of an Israel calendar date. */
export function weekdayOfIso(isoDate: string): Weekday {
  if (!ISO_DATE.test(isoDate)) throw new Error(`weekdayOfIso: bad date ${isoDate}`);
  return new Date(`${isoDate}T00:00:00Z`).getUTCDay() as Weekday;
}

/**
 * The instant at which the Israel wall clock shows `isoDate hour:minute`. For a wall time that
 * does not exist (the spring-forward gap) the result is the first instant after the gap; for a
 * repeated wall time (autumn) the earlier instant is returned.
 */
export function israelWallTimeToInstant(isoDate: string, hour: number, minute = 0): Date {
  if (!ISO_DATE.test(isoDate)) throw new Error(`israelWallTimeToInstant: bad date ${isoDate}`);
  const [y, m, d] = isoDate.split('-').map(Number);
  const wallAsUtc = Date.UTC(y, m - 1, d, hour, minute);
  const offsetAt = (instantMs: number) => {
    const p = israelLocalParts(new Date(instantMs));
    return Date.UTC(p.year, p.month - 1, p.day, p.hour, p.minute) - Math.floor(instantMs / 60_000) * 60_000;
  };
  // Try both candidate offsets (before and after any DST change near this wall time) and keep
  // the earliest one that maps back to the requested wall time.
  const candidates = [...new Set([offsetAt(wallAsUtc - 12 * 3_600_000), offsetAt(wallAsUtc + 12 * 3_600_000)])]
    .map((offset) => wallAsUtc - offset)
    .sort((a, b) => a - b);
  for (const c of candidates) {
    const p = israelLocalParts(new Date(c));
    if (p.isoDate === isoDate && p.hour === hour && p.minute === minute) return new Date(c);
  }
  // Non-existent wall time (spring-forward gap): the instant after the gap.
  return new Date(Math.max(...candidates));
}

const BLACKOUT = new Map(IL_BLACKOUT_DATES.map((d) => [d.date, d.reason]));

function toIsraelIso(date: Date | string): string {
  if (typeof date === 'string') {
    if (!ISO_DATE.test(date)) throw new Error(`bad Israel date ${date}`);
    return date;
  }
  return israelDate(date);
}

/** True when the Israel calendar date is inside the generated data's coverage. */
export function isIsraelCalendarCovered(date: Date | string): boolean {
  const iso = toIsraelIso(date);
  return iso >= IL_CALENDAR_COVERAGE.from && iso <= IL_CALENDAR_COVERAGE.to;
}

/**
 * True when the Israel calendar date (of an instant, or a `YYYY-MM-DD` string) is a listed
 * holiday, holiday eve, or day inside the Tishrei / Pesach runs. Outside the generated coverage
 * this returns false; callers that must fail closed check `isIsraelCalendarCovered` first.
 */
export function isIsraelBlackoutDate(date: Date | string): boolean {
  return BLACKOUT.has(toIsraelIso(date));
}

/** Why a date is blacked out (English, from the generator), or null. */
export function israelBlackoutReason(date: Date | string): string | null {
  return BLACKOUT.get(toIsraelIso(date)) ?? null;
}
